/**
 * Baked pit-lane paths (F1 frame), keyed by circuit_key. Generated by
 * `node scripts/fetch-pit-lanes.mjs` from a real car's GPS trace through a
 * pit stop; pit lanes rarely change, so one path per circuit.
 *
 * Import only from the lazily-loaded 3D map chunk.
 */
import baked from "./pit-lanes.json";

export interface PitLanePath {
  x: number[];
  y: number[];
}

const LANES = baked as Record<string, PitLanePath>;

export function getPitLane(circuitKey: number | null | undefined): PitLanePath | null {
  if (circuitKey == null) return null;
  return LANES[String(circuitKey)] ?? null;
}
